"""
VesselOptima — Phase 13: Benchmark Engine

Implements standard institutional maritime baseline strategies to measure
VesselOptima outperformance under identical historical point-in-time constraints.
"""

from __future__ import annotations

import abc
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Dict, List, Optional

from app.engines.backtest.reason_codes import BenchmarkStrategyType
from app.engines.backtest.snapshot import PointInTimeSnapshot


@dataclass
class BenchmarkDecisionResult:
    """Decision output generated by a benchmark policy at a single historical snapshot."""
    strategy_type: BenchmarkStrategyType
    strategy_name: str
    decision_timestamp: datetime
    assignments: List[Dict[str, Any]]
    expected_contribution_usd: float
    realized_contribution_usd: float
    vessel_utilization_pct: float
    details: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "strategy_type": self.strategy_type.value if hasattr(self.strategy_type, "value") else str(self.strategy_type),
            "strategy_name": self.strategy_name,
            "decision_timestamp": self.decision_timestamp.isoformat(),
            "assignments": self.assignments,
            "expected_contribution_usd": self.expected_contribution_usd,
            "realized_contribution_usd": self.realized_contribution_usd,
            "vessel_utilization_pct": self.vessel_utilization_pct,
            "details": self.details,
        }


class BenchmarkStrategy(abc.ABC):
    """Abstract base class for all backtest baseline decision strategies."""
    def __init__(self, name: str, strategy_type: BenchmarkStrategyType, description: str):
        self.name = name
        self.strategy_type = strategy_type
        self.description = description

    @abc.abstractmethod
    def decide(
        self,
        snapshot: PointInTimeSnapshot,
        candidate_pool: List[Dict[str, Any]],
        historical_actuals: Optional[List[Dict[str, Any]]] = None,
    ) -> BenchmarkDecisionResult:
        """Evaluates available opportunities and produces assignments."""
        pass


class NoActionStrategy(BenchmarkStrategy):
    """
    Policy: Do nothing. All vessels remain unassigned / idle in place.
    Baseline floor demonstrating the raw cost of inaction.
    """
    def __init__(self):
        super().__init__(
            name="No Action",
            strategy_type=BenchmarkStrategyType.NO_ACTION,
            description="Vessels maintain current status and take no new cargoes, incurring idle costs.",
        )

    def decide(
        self,
        snapshot: PointInTimeSnapshot,
        candidate_pool: List[Dict[str, Any]],
        historical_actuals: Optional[List[Dict[str, Any]]] = None,
    ) -> BenchmarkDecisionResult:
        assignments = []
        total_idle_cost = 0.0

        for vid, vdata in snapshot.vessels.items():
            daily_opex = float(vdata.get("daily_operating_cost", 7500.0))
            idle_cost = daily_opex * 10.0  # 10 days evaluation window at vessel-specific daily OPEX
            total_idle_cost += idle_cost
            assignments.append({
                "vessel_id": vdata.get("vessel_id", vid),
                "cargo_id": None,
                "status": "IDLE",
                "daily_idle_rate": daily_opex,
                "expected_contribution_usd": -idle_cost,
                "realized_contribution_usd": -idle_cost,
            })

        return BenchmarkDecisionResult(
            strategy_type=self.strategy_type,
            strategy_name=self.name,
            decision_timestamp=snapshot.timestamp,
            assignments=assignments,
            expected_contribution_usd=-total_idle_cost,
            realized_contribution_usd=-total_idle_cost,
            vessel_utilization_pct=0.0,
            details={"policy": "all_idle"},
        )


class ContinueCurrentEmploymentStrategy(BenchmarkStrategy):
    """
    Policy: Vessels with existing commitments complete them; uncommitted vessels do not take new spot fixtures.
    """
    def __init__(self):
        super().__init__(
            name="Continue Current Employment",
            strategy_type=BenchmarkStrategyType.CONTINUE_CURRENT_EMPLOYMENT,
            description="Honor pre-existing fixtures without contracting any new spot cargoes.",
        )

    def decide(
        self,
        snapshot: PointInTimeSnapshot,
        candidate_pool: List[Dict[str, Any]],
        historical_actuals: Optional[List[Dict[str, Any]]] = None,
    ) -> BenchmarkDecisionResult:
        commitments_by_vessel = {}
        for c in snapshot.commitments:
            commitments_by_vessel[str(c.get("vessel_id"))] = c

        assignments = []
        total_contrib = 0.0
        assigned_count = 0

        for vid, vdata in snapshot.vessels.items():
            v_id_int = vdata.get("vessel_id", vid)
            daily_opex = float(vdata.get("daily_operating_cost", 7500.0))

            if str(vid) in commitments_by_vessel:
                comm = commitments_by_vessel[str(vid)]
                cargo_id = comm.get("cargo_id")
                cargo = snapshot.cargoes.get(str(cargo_id)) if cargo_id else None
                if cargo:
                    qty = float(cargo.get("quantity_mt", 50000.0))
                    fr = float(cargo.get("freight_rate_usd", 20.0))
                    rev = qty * fr
                    # Contractual voyage duration ~ 15 days
                    voyage_cost = daily_opex * 15.0 + 35000.0
                    fixture_contrib = rev - voyage_cost
                else:
                    dwt = float(vdata.get("dwt", 55000.0))
                    fixture_contrib = round(dwt * 18.50 - (daily_opex * 15.0 + 35000.0), 2)

                total_contrib += fixture_contrib
                assigned_count += 1
                assignments.append({
                    "vessel_id": v_id_int,
                    "cargo_id": cargo_id or "COMMITTED",
                    "status": "COMMITTED_CONTINUATION",
                    "expected_contribution_usd": fixture_contrib,
                    "realized_contribution_usd": fixture_contrib,
                })
            else:
                idle_cost = daily_opex * 10.0
                total_contrib -= idle_cost
                assignments.append({
                    "vessel_id": v_id_int,
                    "cargo_id": None,
                    "status": "IDLE",
                    "daily_idle_rate": daily_opex,
                    "expected_contribution_usd": -idle_cost,
                    "realized_contribution_usd": -idle_cost,
                })

        utilization = (assigned_count / len(snapshot.vessels) * 100.0) if snapshot.vessels else 0.0
        return BenchmarkDecisionResult(
            strategy_type=self.strategy_type,
            strategy_name=self.name,
            decision_timestamp=snapshot.timestamp,
            assignments=assignments,
            expected_contribution_usd=round(total_contrib, 2),
            realized_contribution_usd=round(total_contrib, 2),
            vessel_utilization_pct=round(utilization, 1),
            details={"committed_vessels_count": len(commitments_by_vessel)},
        )


class FirstFeasibleStrategy(BenchmarkStrategy):
    """
    Policy: Greedily assigns each vessel to the first feasible cargo encountered.
    Simulates ad-hoc or manual chartering without combinatorial optimization.
    """
    def __init__(self):
        super().__init__(
            name="First Feasible",
            strategy_type=BenchmarkStrategyType.FIRST_FEASIBLE,
            description="Assigns the first feasible cargo to each open vessel in arrival order.",
        )

    def decide(
        self,
        snapshot: PointInTimeSnapshot,
        candidate_pool: List[Dict[str, Any]],
        historical_actuals: Optional[List[Dict[str, Any]]] = None,
    ) -> BenchmarkDecisionResult:
        assigned_cargoes = set()
        assigned_vessels = set()
        assignments = []
        total_contrib = 0.0

        # Sort candidates deterministically by candidate_id
        sorted_candidates = sorted(candidate_pool, key=lambda c: str(c.get("candidate_id", "")))

        for c in sorted_candidates:
            vid = str(c.get("vessel_id"))
            cid = str(c.get("cargo_id"))
            if vid not in assigned_vessels and cid not in assigned_cargoes:
                assigned_vessels.add(vid)
                assigned_cargoes.add(cid)
                contrib = float(c.get("expected_contribution_usd", c.get("net_contribution", 0.0)))
                total_contrib += contrib
                assignments.append({
                    "vessel_id": int(vid) if str(vid).isdigit() else vid,
                    "cargo_id": int(cid) if str(cid).isdigit() else cid,
                    "status": "ASSIGNED",
                    "expected_contribution_usd": contrib,
                    "realized_contribution_usd": contrib,
                })

        # Add idle vessels using vessel-specific OPEX
        for vid, vdata in snapshot.vessels.items():
            if str(vid) not in assigned_vessels:
                daily_opex = float(vdata.get("daily_operating_cost", 7500.0))
                idle_cost = daily_opex * 10.0
                total_contrib -= idle_cost
                assignments.append({
                    "vessel_id": vdata.get("vessel_id", vid),
                    "cargo_id": None,
                    "status": "IDLE",
                    "daily_idle_rate": daily_opex,
                    "expected_contribution_usd": -idle_cost,
                    "realized_contribution_usd": -idle_cost,
                })

        util = (len(assigned_vessels) / len(snapshot.vessels) * 100.0) if snapshot.vessels else 0.0
        return BenchmarkDecisionResult(
            strategy_type=self.strategy_type,
            strategy_name=self.name,
            decision_timestamp=snapshot.timestamp,
            assignments=assignments,
            expected_contribution_usd=round(total_contrib, 2),
            realized_contribution_usd=round(total_contrib, 2),
            vessel_utilization_pct=round(util, 1),
            details={"assigned_count": len(assigned_vessels)},
        )


class BestExpectedContributionStrategy(BenchmarkStrategy):
    """
    Policy: Greedily assigns the candidate with the highest expected contribution,
    one by one, until no more feasible assignments exist.
    Operates strictly on the same information available at decision timestamp T.
    """
    def __init__(self):
        super().__init__(
            name="Best Expected Contribution",
            strategy_type=BenchmarkStrategyType.BEST_EXPECTED_CONTRIBUTION,
            description="Greedy priority sorting by single-voyage expected contribution without global MILP.",
        )

    def decide(
        self,
        snapshot: PointInTimeSnapshot,
        candidate_pool: List[Dict[str, Any]],
        historical_actuals: Optional[List[Dict[str, Any]]] = None,
    ) -> BenchmarkDecisionResult:
        sorted_candidates = sorted(
            candidate_pool,
            key=lambda c: float(c.get("expected_contribution_usd", c.get("net_contribution", 0.0))),
            reverse=True,
        )

        assigned_cargoes = set()
        assigned_vessels = set()
        assignments = []
        total_contrib = 0.0

        for c in sorted_candidates:
            vid = str(c.get("vessel_id"))
            cid = str(c.get("cargo_id"))
            if vid not in assigned_vessels and cid not in assigned_cargoes:
                contrib = float(c.get("expected_contribution_usd", c.get("net_contribution", 0.0)))
                if contrib > 0:
                    assigned_vessels.add(vid)
                    assigned_cargoes.add(cid)
                    total_contrib += contrib
                    assignments.append({
                        "vessel_id": int(vid) if str(vid).isdigit() else vid,
                        "cargo_id": int(cid) if str(cid).isdigit() else cid,
                        "status": "ASSIGNED",
                        "expected_contribution_usd": contrib,
                        "realized_contribution_usd": contrib,
                    })

        # Add remaining unassigned vessels as idle with vessel-specific OPEX
        for vid, vdata in snapshot.vessels.items():
            if str(vid) not in assigned_vessels:
                daily_opex = float(vdata.get("daily_operating_cost", 7500.0))
                idle_cost = daily_opex * 10.0
                total_contrib -= idle_cost
                assignments.append({
                    "vessel_id": vdata.get("vessel_id", vid),
                    "cargo_id": None,
                    "status": "IDLE",
                    "daily_idle_rate": daily_opex,
                    "expected_contribution_usd": -idle_cost,
                    "realized_contribution_usd": -idle_cost,
                })

        util = (len(assigned_vessels) / len(snapshot.vessels) * 100.0) if snapshot.vessels else 0.0
        return BenchmarkDecisionResult(
            strategy_type=self.strategy_type,
            strategy_name=self.name,
            decision_timestamp=snapshot.timestamp,
            assignments=assignments,
            expected_contribution_usd=round(total_contrib, 2),
            realized_contribution_usd=round(total_contrib, 2),
            vessel_utilization_pct=round(util, 1),
            details={"assigned_count": len(assigned_vessels)},
        )


class HistoricalActualOutcomeBenchmark(BenchmarkStrategy):
    """
    Outcome Benchmark: Represents what human operators actually chartered historically.
    When no authentic operator charter log is present, explicitly declares synthetic
    benchmark assumption provenance to prevent misrepresentation.
    """
    def __init__(self):
        super().__init__(
            name="Historical Actual",
            strategy_type=BenchmarkStrategyType.HISTORICAL_ACTUAL,
            description="Ex-post actual realized chartering outcome achieved by human operators.",
        )

    def decide(
        self,
        snapshot: PointInTimeSnapshot,
        candidate_pool: List[Dict[str, Any]],
        historical_actuals: Optional[List[Dict[str, Any]]] = None,
    ) -> BenchmarkDecisionResult:
        actuals = historical_actuals or []
        total_realized = 0.0
        assignments = []
        is_synthetic = False

        if actuals:
            for item in actuals:
                contrib = float(item.get("realized_contribution_usd", item.get("contribution", 0.0)))
                total_realized += contrib
                assignments.append({
                    "vessel_id": item.get("vessel_id", 1),
                    "cargo_id": item.get("cargo_id"),
                    "status": "HISTORICAL_ACTUAL",
                    "expected_contribution_usd": contrib,
                    "realized_contribution_usd": contrib,
                })
            util = (len(actuals) / len(snapshot.vessels) * 100.0) if snapshot.vessels else 60.0
            provenance = "AUTHENTIC_OPERATOR_LOG"
        else:
            is_synthetic = True
            provenance = "SYNTHETIC_BENCHMARK_ASSUMPTION"
            for vid, vdata in snapshot.vessels.items():
                daily_opex = float(vdata.get("daily_operating_cost", 7500.0))
                vclass = str(vdata.get("vessel_class", "Supramax"))
                daily_tce = 22000.0 if "Cape" in vclass else (14000.0 if "Supra" in vclass else 11000.0)
                nominal_margin = round((daily_tce - daily_opex) * 10.0, 2)
                total_realized += nominal_margin
                assignments.append({
                    "vessel_id": vdata.get("vessel_id", vid),
                    "cargo_id": None,
                    "status": "HISTORICAL_ACTUAL_SYNTHETIC",
                    "expected_contribution_usd": nominal_margin,
                    "realized_contribution_usd": nominal_margin,
                })
            util = 60.0

        return BenchmarkDecisionResult(
            strategy_type=self.strategy_type,
            strategy_name=self.name,
            decision_timestamp=snapshot.timestamp,
            assignments=assignments,
            expected_contribution_usd=round(total_realized, 2),
            realized_contribution_usd=round(total_realized, 2),
            vessel_utilization_pct=round(util, 1),
            details={
                "is_ex_post_outcome_baseline": True,
                "provenance": provenance,
                "is_synthetic_assumption": is_synthetic,
                "has_authentic_actuals": not is_synthetic,
                "disclaimer": (
                    "No authentic operator charter log present in historical dataset; "
                    "values derived from vessel class TCE benchmark assumptions."
                    if is_synthetic else "Authentic operator execution log verified."
                ),
            },
        )


def get_default_benchmarks() -> List[BenchmarkStrategy]:
    """Returns the 5 required benchmark strategies."""
    return [
        NoActionStrategy(),
        ContinueCurrentEmploymentStrategy(),
        FirstFeasibleStrategy(),
        BestExpectedContributionStrategy(),
        HistoricalActualOutcomeBenchmark(),
    ]
